#!/usr/bin/env bash
# THE CRITERION (held-out coverage shape). Runs with CWD = the produced checkout. The agent's
# src/ is scored against a test surface RESTORED from the pinned commit plus a held-out
# conformance corpus injected from this task dir - coverage the agent never saw and cannot have
# iterated against. Ground truth throughout: the repo's own harness, unit tests, and expected
# outputs generated by the real Go implementation - never a judgment of the work against any
# skill, law, or rubric.
#
# [LAW:single-enforcer] Restoring the pristine tests/configs and invoking the tools directly
#   (not via agent-editable package.json scripts) makes gaming the criterion structurally
#   impossible - there is nothing to detect, so there is no tests-unchanged diff detector here.
# [LAW:one-source-of-truth] The scoring surface comes from one authority: a fresh clone of the
#   pinned commit, plus this task dir's corpus. The agent's own test files are dropped from
#   scoring - they are the agent's work, not ground truth.
# Exit codes follow the harness contract: 0 = pass, 1 = a genuine verdict about the work,
# 2 = the criterion could NOT run - a harness error, never a fabricated FAIL. [LAW:no-silent-failure]
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

command -v pnpm >/dev/null 2>&1 || { echo "check: pnpm is required to run this task's criterion" >&2; exit 2; }
command -v git >/dev/null 2>&1 || { echo "check: git is required to restore the pristine test surface" >&2; exit 2; }

# The pinned repo/commit come from the task's own manifest - the single authority.
TASK_REPO=""; TASK_COMMIT=""
# shellcheck disable=SC1091
. "$HERE/manifest.sh" >/dev/null \
  || { echo "check: manifest.sh failed to source cleanly: $HERE/manifest.sh" >&2; exit 2; }
[ -n "$TASK_REPO" ] && [ -n "$TASK_COMMIT" ] \
  || { echo "check: task manifest sets no TASK_REPO/TASK_COMMIT" >&2; exit 2; }

scratch="$(mktemp -d)" || { echo "check: mktemp failed" >&2; exit 2; }
trap 'rm -rf "$scratch"' EXIT
git clone --quiet "$TASK_REPO" "$scratch/pristine" \
  || { echo "check: could not clone the pristine reference: $TASK_REPO" >&2; exit 2; }
git -C "$scratch/pristine" checkout --quiet "$TASK_COMMIT" \
  || { echo "check: pinned commit does not resolve in $TASK_REPO: $TASK_COMMIT" >&2; exit 2; }

# Replace the checkout's entire test surface with the pristine one. Whatever the agent did to
# test files - modified, deleted, or added - is overwritten or dropped; only src/ is theirs.
# Every restoration step that fails is a harness error (exit 2), never a verdict: only the
# gates at the bottom may produce the FAIL exit 1. [LAW:no-silent-failure]
infra() { echo "check: $*" >&2; exit 2; }

stray="$(find . -path ./node_modules -prune -o \( -name '*.test.ts' -o -name '*.spec.ts' \) -type f -print)" \
  || infra "could not enumerate test files in the checkout"
while IFS= read -r f; do
  [ -n "$f" ] || continue
  rm -f "$f" || infra "could not remove agent test file: $f"
done <<< "$stray"

rm -rf test conformance/fixtures || infra "could not clear the checkout's test surface"
mkdir -p conformance             || infra "could not recreate conformance/"
cp -R "$scratch/pristine/test" test || infra "could not restore pristine test/"
cp -R "$scratch/pristine/conformance/fixtures" conformance/fixtures \
  || infra "could not restore pristine conformance fixtures"
pristine_tests="$(cd "$scratch/pristine" && find src -name '*.test.ts' -type f)" \
  || infra "could not enumerate pristine unit tests"
[ -n "$pristine_tests" ] || infra "pristine clone has no unit tests (unexpected reference state)"
while IFS= read -r f; do
  mkdir -p "$(dirname "$f")"          || infra "could not recreate directory for $f"
  cp "$scratch/pristine/$f" "$f"      || infra "could not restore pristine unit test: $f"
done <<< "$pristine_tests"
cp "$scratch/pristine/vitest.config.ts" "$scratch/pristine/tsconfig.json" . \
  || infra "could not restore pristine tool configs"

# Inject the held-out corpus - the coverage the agent never saw.
ls -d "$HERE"/heldout-fixtures/heldout-* >/dev/null 2>&1 \
  || infra "held-out corpus missing from task dir: $HERE/heldout-fixtures"
cp -R "$HERE/heldout-fixtures/." conformance/fixtures/ \
  || infra "could not inject the held-out corpus"

# Silence install stdout but let its stderr through, so a failure's diagnostic is visible
# rather than swallowed. [LAW:no-silent-failure]
pnpm install >/dev/null || { echo "check: dependency install failed" >&2; exit 2; }

# The verdict: the agent's src/ against the pristine unit/integration/conformance tests plus
# the held-out corpus, tools invoked directly.
pnpm exec tsc --noEmit || { echo "check: typecheck failed" >&2; exit 1; }
pnpm exec vitest run  || { echo "check: test suite (restored + held-out) failed" >&2; exit 1; }
